{"content": "import flask


def test_template_global_with_args(app, app_ctx):
    """Test that template_global decorator accepts functions with arguments."""
    @app.template_global()
    def double(n):
        return 2 * n

    assert "double" in app.jinja_env.globals.keys()
    assert app.jinja_env.globals["double"] is double
    assert app.jinja_env.globals["double"](21) == 42

    rv = flask.render_template_string("{{ double(21) }}")
    assert rv == "42"", "path": "tests/test_template_global_args.py"}
